package app.velyntora.windows.app.home;
import app.velyntora.windows.app.EditorTheme;
import app.velyntora.windows.document.DocumentIO;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.nio.file.Path;
import java.util.function.Consumer;
/** Shared Windows/Linux start screen. Coordinates follow the 1536x960 reference. */
public final class HomeScreen extends JPanel {
 public static final Color BACKGROUND=new Color(21,25,34),CARD=new Color(13,23,37),MUTED=new Color(183,190,204),PURPLE=new Color(174,47,191),BORDER=new Color(42,54,69);
 private final JPanel hero,right,recentCard;private final JLabel logo,brand,pilot,title,description,credit,recentTitle,empty;
 private final HomeButton create,open,more,preferences,help,recover;
 private final JList<String> recent=new JList<>(new DefaultListModel<>());private final JScrollPane recentScroll;
 private final Consumer<String> openRecent;private double scale=1;
 public HomeScreen(BufferedImage art,BufferedImage logoImage,Runnable createAction,Runnable openAction,Consumer<String> openRecent,Runnable preferencesAction,Runnable helpAction,Runnable recoveryAction){
  this.openRecent=openRecent;setName("Inicio de Velyntora Drawing");setLayout(null);setBackground(BACKGROUND);
  hero=new JPanel(null){protected void paintComponent(Graphics graphics){super.paintComponent(graphics);Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);double zoom=Math.max(getWidth()/(double)art.getWidth(),getHeight()/(double)art.getHeight());int w=(int)Math.ceil(art.getWidth()*zoom),h=(int)Math.ceil(art.getHeight()*zoom);g.drawImage(art,(getWidth()-w)/2,(getHeight()-h)/2,w,h,null);g.setColor(new Color(0,0,0,102));g.fillRect(0,0,getWidth(),getHeight());g.dispose();}};hero.setBackground(BACKGROUND);add(hero);
  right=new JPanel(null);right.setBackground(BACKGROUND);add(right);
  title=label("DIBUJO",SwingConstants.CENTER);hero.add(title);description=label("<html><div style='text-align:center'>Crea ilustraciones, edita imágenes<br>y da vida a tus ideas.</div></html>",SwingConstants.CENTER);hero.add(description);
  create=button("Crear ilustración",true,createAction);hero.add(create);open=button("Abrir imagen",false,openAction);hero.add(open);recover=button("Recuperar documento",false,recoveryAction);recover.setVisible(false);hero.add(recover);
  credit=label("Powered By Zaskar Startup",SwingConstants.CENTER);hero.add(credit);
  BufferedImage trimmed=trim(logoImage);logo=new JLabel(){protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);double ratio=Math.min(getWidth()/(double)trimmed.getWidth(),getHeight()/(double)trimmed.getHeight());int w=(int)Math.round(trimmed.getWidth()*ratio),h=(int)Math.round(trimmed.getHeight()*ratio);g.drawImage(trimmed,(getWidth()-w)/2,(getHeight()-h)/2,w,h,null);g.dispose();}};logo.setName("Logotipo Velyntora");right.add(logo);
  brand=label("Drawing",SwingConstants.CENTER);right.add(brand);pilot=label("VERSIÓN PILOTO · Prototipo en desarrollo",SwingConstants.CENTER);pilot.setForeground(MUTED);right.add(pilot);
  recentCard=new JPanel(null){protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(CARD);g.fillRoundRect(0,0,getWidth(),getHeight(),6,6);g.setColor(BORDER);g.drawRoundRect(0,0,getWidth()-1,getHeight()-1,6,6);g.dispose();}};recentCard.setOpaque(false);right.add(recentCard);
  recentTitle=label("Proyectos recientes",SwingConstants.LEFT);recentCard.add(recentTitle);more=button("Ver más »",false,this::showRecent);recentCard.add(more);empty=label("Tus proyectos recientes aparecerán aquí.",SwingConstants.CENTER);empty.setForeground(MUTED);recentCard.add(empty);
  recent.setName("Proyectos recientes");recent.setBackground(CARD);recent.setForeground(EditorTheme.TEXT);recent.setSelectionBackground(new Color(53,62,84));recent.setSelectionForeground(Color.WHITE);recent.setCellRenderer((list,path,index,selected,focused)->{JLabel row=new JLabel(Path.of(path).getFileName().toString());row.setFont(EditorTheme.font((float)(16*scale)));row.setBorder(BorderFactory.createEmptyBorder(8,0,8,0));row.setOpaque(true);row.setBackground(selected?list.getSelectionBackground():CARD);row.setForeground(EditorTheme.TEXT);row.setToolTipText(path);return row;});recent.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2&&recent.getSelectedValue()!=null)openRecent.accept(recent.getSelectedValue());}});recent.getInputMap().put(KeyStroke.getKeyStroke("ENTER"),"open");recent.getActionMap().put("open",new AbstractAction(){public void actionPerformed(ActionEvent e){if(recent.getSelectedValue()!=null)openRecent.accept(recent.getSelectedValue());}});recentScroll=new JScrollPane(recent);recentScroll.setBorder(BorderFactory.createEmptyBorder());recentScroll.getViewport().setBackground(CARD);recentCard.add(recentScroll);
  preferences=button("Preferencias de Velyntora",false,preferencesAction);right.add(preferences);help=button("? Ayuda",false,helpAction);right.add(help);refreshRecent();
 }
 private static BufferedImage trim(BufferedImage image){int left=image.getWidth(),top=image.getHeight(),right=0,bottom=0;for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)if((image.getRGB(x,y)>>>24)>32){left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x+1);bottom=Math.max(bottom,y+1);}return right>left&&bottom>top?image.getSubimage(left,top,right-left,bottom-top):image;}
 private static JLabel label(String text,int alignment){JLabel label=new JLabel(text,alignment);label.setForeground(EditorTheme.TEXT);label.setName(text);return label;}
 private static HomeButton button(String text,boolean primary,Runnable action){HomeButton button=new HomeButton(text,primary);button.setName(text);button.getAccessibleContext().setAccessibleName(text);button.addActionListener(e->action.run());return button;}
 public void refreshRecent(){setRecentProjects(DocumentIO.recent());}
 public void setRecentProjects(java.util.List<String> paths){DefaultListModel<String> model=(DefaultListModel<String>)recent.getModel();model.clear();paths.stream().limit(3).forEach(model::addElement);boolean has=!model.isEmpty();empty.setVisible(!has);recentScroll.setVisible(has);}
 public void setRecoveryAvailable(boolean available){recover.setVisible(available);revalidate();}
 private void showRecent(){java.util.List<String> paths=DocumentIO.recent();if(paths.isEmpty()){JOptionPane.showMessageDialog(this,"Tus proyectos recientes aparecerán aquí al abrir o guardar un documento.","Proyectos recientes",JOptionPane.INFORMATION_MESSAGE);return;}JList<String> all=new JList<>(paths.toArray(String[]::new));all.setSelectedIndex(0);all.setCellRenderer((list,path,index,selected,focused)->{JLabel row=new JLabel(Path.of(path).getFileName()+"    "+path);row.setOpaque(true);row.setBackground(selected?list.getSelectionBackground():list.getBackground());row.setForeground(selected?list.getSelectionForeground():list.getForeground());row.setBorder(BorderFactory.createEmptyBorder(8,8,8,8));return row;});JScrollPane scroll=new JScrollPane(all);scroll.setPreferredSize(new Dimension(680,300));if(JOptionPane.showConfirmDialog(this,scroll,"Proyectos recientes · Abrir",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION&&all.getSelectedValue()!=null)openRecent.accept(all.getSelectedValue());}
 public void doLayout(){int w=getWidth(),h=getHeight(),left=(int)Math.round(w*.36),rw=w-left;scale=Math.max(.6,Math.min(w/1536.,h/960.));double s=scale;int margin=(int)Math.round(28*s);hero.setBounds(0,0,left,h);right.setBounds(left,0,rw,h);
  title.setBounds(12,(int)(h*.375),left-24,(int)(39*s));description.setBounds(12,title.getY()+title.getHeight()+(int)(4*s),left-24,(int)(48*s));int buttonX=(int)(21*s),buttonW=left-buttonX*2,buttonH=(int)(62*s);create.setBounds(buttonX,(int)(h*.488),buttonW,buttonH);open.setBounds(buttonX,create.getY()+buttonH+(int)(15*s),buttonW,buttonH);recover.setBounds(buttonX,open.getY()+buttonH+(int)(12*s),buttonW,(int)(48*s));credit.setBounds(10,h-(int)(48*s),left-20,(int)(30*s));
  logo.setBounds((rw-(int)(210*s))/2,(int)(54*s),(int)(210*s),(int)(28*s));brand.setBounds(margin,(int)(109*s),rw-2*margin,(int)(34*s));pilot.setBounds(margin,(int)(153*s),rw-2*margin,(int)(25*s));recentCard.setBounds(margin,(int)(203*s),rw-margin*2,(int)(194*s));int cw=recentCard.getWidth();recentTitle.setBounds((int)(20*s),(int)(28*s),cw-(int)(172*s),(int)(30*s));more.setBounds(cw-(int)(140*s),(int)(14*s),(int)(120*s),(int)(58*s));empty.setBounds((int)(20*s),(int)(94*s),cw-(int)(40*s),(int)(64*s));recentScroll.setBounds((int)(20*s),(int)(80*s),cw-(int)(40*s),(int)(101*s));int footerY=recentCard.getY()+recentCard.getHeight()+(int)(14*s);help.setBounds(rw-margin-(int)(106*s),footerY,(int)(106*s),(int)(58*s));preferences.setBounds(help.getX()-(int)(237*s),footerY,(int)(227*s),(int)(58*s));
  font(title,32*s,true);font(description,20*s,false);font(credit,16*s,true);font(brand,26*s,true);font(pilot,16*s,false);font(recentTitle,20*s,true);font(empty,17*s,false);for(HomeButton button:new HomeButton[]{create,open,recover,more,preferences,help})font(button,16*s,false);

 }
 private static void font(JComponent component,double size,boolean bold){Font font=EditorTheme.font((float)size).deriveFont(bold?Font.BOLD:Font.PLAIN);if(!font.equals(component.getFont()))component.setFont(font);}
 private static final class HomeButton extends JButton {
  private final boolean primary;HomeButton(String label,boolean primary){super(label);this.primary=primary;setBorder(BorderFactory.createEmptyBorder(4,8,4,8));setContentAreaFilled(false);setFocusPainted(false);setForeground(Color.WHITE);setRolloverEnabled(true);}
  protected void paintComponent(Graphics graphics){Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);Color fill=primary?PURPLE:CARD;if(getModel().isPressed())fill=fill.darker();else if(getModel().isRollover())fill=fill.brighter();g.setColor(fill);g.fillRoundRect(0,0,getWidth(),getHeight(),6,6);g.setColor(hasFocus()?EditorTheme.ACCENT:BORDER);g.drawRoundRect(0,0,getWidth()-1,getHeight()-1,6,6);g.dispose();super.paintComponent(graphics);}
 }
}
